import std.io

pub type AppError = Failed(String)

record Cell { n: Int64 }

pub fn main() effect io -> Result<(), AppError> {
    let xs = [100, 200, 300]
    let d = Dyn<Iterator<Int64> >(xs.iterator())
    var acc: Int64 = 0
    var i: Int64 = 0
    while i < 120000 {
        let c = Cell { n: i }
        acc = acc + c.n
        i = i + 1
    }
    io.println("${acc}")
    let a = d.next()
    match a {
        Some(v) => { io.println("${v}") }
        None => { io.println("none") }
    }
    let b = d.next()
